package pt

import (
	"math"
	"math/rand"
	"testing"
)

// sobRefPoints holds the first 8 points of dimensions 0..7 of the canonical
// (unscrambled, Gray-code order) Sobol sequence, generated by Frances Kuo's
// reference implementation (sobol.cc) with the Joe & Kuo direction file.
// The test pins our generator to that published reference.
var sobRefPoints = [8][8]float64{
	{0, 0, 0, 0, 0, 0, 0, 0},
	{0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5},
	{0.75, 0.25, 0.25, 0.25, 0.75, 0.75, 0.25, 0.75},
	{0.25, 0.75, 0.75, 0.75, 0.25, 0.25, 0.75, 0.25},
	{0.375, 0.375, 0.625, 0.875, 0.375, 0.125, 0.375, 0.875},
	{0.875, 0.875, 0.125, 0.375, 0.875, 0.625, 0.875, 0.375},
	{0.625, 0.125, 0.875, 0.625, 0.625, 0.875, 0.125, 0.125},
	{0.125, 0.625, 0.375, 0.125, 0.125, 0.375, 0.625, 0.625},
}

func TestSobolMatchesReference(t *testing.T) {
	for i := 0; i < 8; i++ {
		for d := 0; d < 8; d++ {
			got := float64(sobolRawPoint(uint64(i), d)) / math.Pow(2, 64)
			want := sobRefPoints[i][d]
			if math.Abs(got-want) > 1e-12 {
				t.Fatalf("point %d dim %d = %v, want %v", i, d, got, want)
			}
		}
	}
}

func TestSobolValueRange(t *testing.T) {
	s := NewSobol(42)
	for pixel := int64(0); pixel < 50; pixel++ {
		for sample := int64(0); sample < 50; sample++ {
			for dim := uint64(0); dim < 40; dim++ {
				v := s.Value(pixel, sample, dim)
				if !(v >= 0 && v < 1) {
					t.Fatalf("Value(%d,%d,%d) = %v out of [0,1)", pixel, sample, dim, v)
				}
			}
		}
	}
}

func TestSobolDeterministic(t *testing.T) {
	a := NewSobol(1234)
	b := NewSobol(1234)
	for pixel := int64(0); pixel < 20; pixel++ {
		for sample := int64(0); sample < 20; sample++ {
			for dim := uint64(0); dim < 20; dim++ {
				if x, y := a.Value(pixel, sample, dim), b.Value(pixel, sample, dim); x != y {
					t.Fatalf("nondeterministic at (%d,%d,%d): %v vs %v", pixel, sample, dim, x, y)
				}
			}
		}
	}
}

func TestSobolSeedChangesSequence(t *testing.T) {
	a := NewSobol(1)
	b := NewSobol(2)
	same := 0
	for sample := int64(0); sample < 100; sample++ {
		if a.Value(0, sample, 0) == b.Value(0, sample, 0) {
			same++
		}
	}
	if same > 1 {
		t.Fatalf("seeds 1 and 2 agree on %d/100 samples; scramble not applied", same)
	}
}

// TestSobolPixelDisjoint verifies that two pixels do not reuse the same
// point set, which is the reason each pixel gets its own digital shift.
func TestSobolPixelDisjoint(t *testing.T) {
	s := NewSobol(7)
	same := 0
	for sample := int64(0); sample < 256; sample++ {
		for dim := uint64(0); dim < 3; dim++ {
			if s.Value(10, sample, dim) == s.Value(11, sample, dim) {
				same++
			}
		}
	}
	if same > 2 {
		t.Fatalf("pixels 10 and 11 share %d/768 values", same)
	}
}

func TestSobolStratification(t *testing.T) {
	// A 2D digital shift preserves the (0,m,2)-net property: across 64
	// samples per pixel, each of the 8x8 elementary intervals must receive
	// exactly one point.
	s := NewSobol(99)
	for pixel := int64(0); pixel < 20; pixel++ {
		counts := make(map[int]int)
		for sample := int64(0); sample < 64; sample++ {
			x := int(s.Value(pixel, sample, 0) * 8)
			y := int(s.Value(pixel, sample, 1) * 8)
			counts[y*8+x]++
		}
		if len(counts) != 64 {
			t.Fatalf("pixel %d covered %d/64 cells, not stratified", pixel, len(counts))
		}
		for cell, n := range counts {
			if n != 1 {
				t.Fatalf("pixel %d cell %d has %d points", pixel, cell, n)
			}
		}
	}
}

func TestSobolDimensionExhaustion(t *testing.T) {
	s := NewSobol(5)
	// Dimensions beyond the table must still be deterministic, finite and in
	// range, and must differ from the first block.
	for _, dim := range []uint64{sobolMaxDims, sobolMaxDims + 1, 5000, 1 << 40} {
		a := s.Value(3, 9, dim)
		b := s.Value(3, 9, dim)
		if a != b {
			t.Fatalf("exhausted dim %d nondeterministic", dim)
		}
		if !(a >= 0 && a < 1) {
			t.Fatalf("exhausted dim %d value %v out of range", dim, a)
		}
		if a == s.Value(3, 9, dim-sobolMaxDims) {
			t.Fatalf("exhausted dim %d repeats dim %d", dim, dim-sobolMaxDims)
		}
	}
}

func TestSobolNegativeIndices(t *testing.T) {
	s := NewSobol(11)
	if s.Value(-5, -9, 0) != s.Value(0, 0, 0) {
		t.Fatal("negative pixel/sample should clamp to zero")
	}
	r := NewSobolRand(s, -3, -4)
	if r.Dimension() != 0 || r.SampleIndex() != 0 {
		t.Fatal("negative indices should clamp in NewSobolRand")
	}
	// Negative Skip is a defined no-op.
	before := r.Dimension()
	r.Skip(-10)
	if r.Dimension() != before {
		t.Fatal("negative Skip should be a no-op")
	}
	// n <= 0 Intn returns 0 rather than panicking.
	if got := r.Intn(0); got != 0 {
		t.Fatalf("Intn(0) = %d, want 0", got)
	}
	if got := r.Intn(-7); got != 0 {
		t.Fatalf("Intn(-7) = %d, want 0", got)
	}
}

func TestSobolNonFiniteSeed(t *testing.T) {
	for _, seed := range []float64{math.NaN(), math.Inf(1), math.Inf(-1)} {
		if _, err := NewSobolFromSeed(seed); err != ErrNonFiniteSeed {
			t.Fatalf("NewSobolFromSeed(%v) err = %v, want ErrNonFiniteSeed", seed, err)
		}
	}
	for _, seed := range []float64{0, -0, 1, -1, 3.14159, math.MaxFloat64} {
		if _, err := NewSobolFromSeed(seed); err != nil {
			t.Fatalf("NewSobolFromSeed(%v) unexpected error %v", seed, err)
		}
	}
}

func TestSobolJumpEquivalence(t *testing.T) {
	s := NewSobol(2024)
	// Skipping dimensions must equal consuming them.
	a := NewSobolRand(s, 7, 3)
	a.Skip(12)
	b := NewSobolRand(s, 7, 3)
	for i := 0; i < 12; i++ {
		b.Float64()
	}
	for i := 0; i < 8; i++ {
		if x, y := a.Float64(), b.Float64(); x != y {
			t.Fatalf("dimension skip diverged at %d: %v vs %v", i, x, y)
		}
	}
	// Seeking to a sample must equal skipping there, and both must equal
	// direct Value lookups.
	c := NewSobolRand(s, 7, 3)
	c.SkipSamples(1000)
	if c.SampleIndex() != 1003 {
		t.Fatalf("SkipSamples left sample index %d, want 1003", c.SampleIndex())
	}
	c.SeekTo(7, 1003, 0)
	for dim := uint64(0); dim < 16; dim++ {
		if got, want := c.Float64(), s.Value(7, 1003, dim); got != want {
			t.Fatalf("seek dim %d = %v, want %v", dim, got, want)
		}
	}
}

func TestSobolTraceSamplesAudit(t *testing.T) {
	s := NewSobol(31337)
	trace := s.TraceSamples(4, 5, 10)
	for d := uint64(0); d < 10; d++ {
		if trace[d] != s.Value(4, 5, d) {
			t.Fatalf("trace dim %d = %v, want %v", d, trace[d], s.Value(4, 5, d))
		}
	}
	if s.TraceSamples(0, 0, 0) != nil {
		t.Fatal("non-positive trace length should be nil")
	}
}

func TestSobolConcurrentReads(t *testing.T) {
	s := NewSobol(8080)
	type key struct {
		pixel, sample int64
		dim           uint64
	}
	want := make(map[key]float64)
	for p := int64(0); p < 8; p++ {
		for n := int64(0); n < 8; n++ {
			for d := uint64(0); d < 8; d++ {
				want[key{p, n, d}] = s.Value(p, n, d)
			}
		}
	}
	const goroutines = 16
	done := make(chan bool, goroutines)
	for g := 0; g < goroutines; g++ {
		go func() {
			for p := int64(0); p < 8; p++ {
				for n := int64(0); n < 8; n++ {
					for d := uint64(0); d < 8; d++ {
						if got := s.Value(p, n, d); got != want[key{p, n, d}] {
							done <- false
							return
						}
					}
				}
			}
			done <- true
		}()
	}
	for g := 0; g < goroutines; g++ {
		if !<-done {
			t.Fatal("concurrent reads disagreed with serial reads")
		}
	}
}

func TestSobolLowDiscrepancy(t *testing.T) {
	// Mean error of a smooth function should beat plain random by a wide
	// margin at the same sample count.
	s := NewSobol(3)
	const n = 4096
	var sum float64
	for i := int64(0); i < n; i++ {
		sum += s.Value(0, i, 0)
	}
	mean := sum / n
	if math.Abs(mean-0.5) > 1e-3 {
		t.Fatalf("Sobol mean = %v, want ~0.5", mean)
	}
	// Plain random with the same count would typically drift by ~1/sqrt(n).
	var rsum float64
	rnd := rand.New(rand.NewSource(1))
	for i := 0; i < n; i++ {
		rsum += rnd.Float64()
	}
	rmean := rsum / n
	if math.Abs(mean-0.5) >= math.Abs(rmean-0.5) {
		t.Fatalf("Sobol mean error %v not better than random %v", math.Abs(mean-0.5), math.Abs(rmean-0.5))
	}
}

func TestSobolSeedForIteration(t *testing.T) {
	if SobolSeedForIteration(1, 0) != 1 {
		t.Fatal("iteration 0 must preserve the seed")
	}
	seen := make(map[uint64]bool)
	for i := 0; i <= 100; i++ {
		v := SobolSeedForIteration(1, i)
		if seen[v] {
			t.Fatalf("iteration seed collision at %d", i)
		}
		seen[v] = true
	}
	if SobolSeedForIteration(1, -3) != 1 {
		t.Fatal("negative iteration should be treated as 0")
	}
}

func TestOrthonormalBasis(t *testing.T) {
	dirs := []Vector{
		{0, 0, 1}, {0, 0, -1}, {0, 1, 0}, {0, -1, 0},
		{1, 0, 0}, {-1, 0, 0},
		{0.3, -0.2, 0.93}, {-0.5, 0.5, 0.707}, {1e-9, 1e-9, -1},
	}
	for _, n := range dirs {
		n = n.Normalize()
		s, tt := OrthonormalBasis(n)
		if math.Abs(s.Dot(n)) > 1e-9 || math.Abs(tt.Dot(n)) > 1e-9 {
			t.Fatalf("basis not perpendicular to %v", n)
		}
		if math.Abs(s.Dot(tt)) > 1e-9 {
			t.Fatalf("basis vectors not orthogonal for %v", n)
		}
		if math.Abs(s.Length()-1) > 1e-9 || math.Abs(tt.Length()-1) > 1e-9 {
			t.Fatalf("basis vectors not unit length for %v", n)
		}
	}
}

func TestConcentricDisk(t *testing.T) {
	// Every output must be inside the unit disk, the origin maps to itself,
	// and values must be deterministic and bounded.
	if x, y := ConcentricDisk(0.5, 0.5); x != 0 || y != 0 {
		t.Fatalf("center maps to (%v,%v), want (0,0)", x, y)
	}
	maxR := 0.0
	for i := 0; i < 100; i++ {
		for j := 0; j < 100; j++ {
			u := (float64(i) + 0.5) / 100
			v := (float64(j) + 0.5) / 100
			x, y := ConcentricDisk(u, v)
			r := math.Hypot(x, y)
			if r > 1+1e-12 {
				t.Fatalf("point (%v,%v) outside unit disk (r=%v)", x, y, r)
			}
			if r > maxR {
				maxR = r
			}
			if x2, y2 := ConcentricDisk(u, v); x2 != x || y2 != y {
				t.Fatal("ConcentricDisk not deterministic")
			}
		}
	}
	if maxR < 0.99 {
		t.Fatalf("disk sampling never reaches the edge (max r=%v)", maxR)
	}
}

// TestSmoothIntegrandConverges is the estimator-quality check that is not
// confounded by visibility discontinuities: on a smooth function of two Sobol
// dimensions, the low-discrepancy mean must be far more accurate than random
// sampling at the same count.
func TestSmoothIntegrandConverges(t *testing.T) {
	const n = 256
	f := func(u, v float64) float64 {
		return 1 + 0.5*math.Sin(2*math.Pi*u) + 0.5*math.Cos(2*math.Pi*v)
	}
	const exact = 1.0
	s := NewSobol(9)
	var sobolMSE float64
	const pixels = 32
	for pixel := int64(0); pixel < pixels; pixel++ {
		var sum float64
		for i := int64(0); i < n; i++ {
			sum += f(s.Value(pixel, i, 0), s.Value(pixel, i, 1))
		}
		e := sum/n - exact
		sobolMSE += e * e
	}
	sobolMSE /= pixels
	rnd := rand.New(rand.NewSource(1))
	var randomMSE float64
	for pixel := 0; pixel < pixels; pixel++ {
		var sum float64
		for i := 0; i < n; i++ {
			sum += f(rnd.Float64(), rnd.Float64())
		}
		e := sum/n - exact
		randomMSE += e * e
	}
	randomMSE /= pixels
	if sobolMSE >= randomMSE {
		t.Fatalf("smooth integrand: Sobol MSE %v not below random MSE %v", sobolMSE, randomMSE)
	}
	t.Logf("smooth integrand %d samples: sobol MSE=%.3g random MSE=%.3g", n, sobolMSE, randomMSE)
}
